#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Hidden browser-local evidence search for the public Pages shell.

This UI never fetches the raw notes corpus. The owner explicitly selects a local
`weread_notes_export.json` file once; the browser flattens it into IndexedDB and
subsequent searches stay local to that browser profile.
"""

CSS = r'''
.hidden-evidence-search[hidden]{display:none!important}.hidden-evidence-search{position:fixed;inset:0;z-index:9998;background:rgba(0,0,0,.55);backdrop-filter:blur(8px);display:grid;place-items:start center;padding:7vh 18px 18px}.hes-panel{width:min(920px,100%);max-height:86vh;overflow:hidden;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:22px;box-shadow:0 24px 80px rgba(0,0,0,.28);display:flex;flex-direction:column}.hes-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:18px 20px;border-bottom:1px solid var(--line)}.hes-head h2{margin:0;font-size:18px}.hes-head p{margin:4px 0 0;color:var(--muted);font-size:11px}.hes-close{border:0;background:transparent;color:var(--muted);font-size:23px;cursor:pointer}.hes-tools{display:grid;grid-template-columns:1fr auto auto;gap:8px;padding:14px 20px;border-bottom:1px solid var(--line)}.hes-tools input[type=search],.hes-tools select{border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:12px;padding:10px 12px;font:inherit}.hes-tools button,.hes-actions button{border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:12px;padding:9px 11px;cursor:pointer}.hes-meta{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:10px 20px;color:var(--muted);font-size:11px}.hes-actions{display:flex;gap:7px;flex-wrap:wrap}.hes-results{overflow:auto;padding:4px 20px 20px;display:grid;gap:9px}.hes-result{border:1px solid var(--line);border-radius:14px;padding:12px 14px;background:var(--bg)}.hes-result .kind{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 7px;font-size:9px;color:var(--muted);margin-right:6px}.hes-result b{font-size:12px}.hes-result .meta{font-size:10px;color:var(--muted);margin-top:3px}.hes-result .text{font-family:ui-serif,"Songti SC","STSong",serif;font-size:14px;line-height:1.65;margin-top:8px;white-space:pre-wrap;word-break:break-word}.hes-result a{color:var(--accent);font-size:10px;text-decoration:none}.hes-empty{padding:30px 0;color:var(--muted);text-align:center;font-size:12px}@media(max-width:700px){.hidden-evidence-search{padding:2vh 8px 8px}.hes-panel{max-height:96vh}.hes-tools{grid-template-columns:1fr 105px}.hes-tools button{grid-column:1/-1}.hes-meta{align-items:flex-start}}
'''

HTML = r'''
<div class="hidden-evidence-search" id="hiddenEvidenceSearch" hidden aria-hidden="true">
  <section class="hes-panel" role="dialog" aria-modal="true" aria-labelledby="hesTitle">
    <header class="hes-head"><div><h2 id="hesTitle">私人快搜</h2><p>⌘/Ctrl + Shift + F · 数据只保存在当前浏览器 IndexedDB，不从网站下载原始笔记。</p></div><button class="hes-close" id="hesClose" type="button" aria-label="关闭">×</button></header>
    <div class="hes-tools"><input id="hesQuery" type="search" autocomplete="off" placeholder="搜索正文 / 书名 / 作者 / 章节"><select id="hesKind"><option value="all">全部</option><option value="mark">仅划线</option><option value="review">仅想法</option></select><button id="hesImport" type="button">导入 / 更新本地索引</button><input id="hesFile" type="file" accept="application/json,.json" hidden></div>
    <div class="hes-meta"><span id="hesStatus">尚未导入本地笔记。</span><div class="hes-actions"><button id="hesForget" type="button">清除本地索引</button></div></div>
    <div class="hes-results" id="hesResults"><div class="hes-empty">首次使用请导入本地 <code>weread_notes_export.json</code>。</div></div>
  </section>
</div>
'''

JS = r'''
(()=>{function boot(){const overlay=document.getElementById('hiddenEvidenceSearch');if(!overlay||window.WeReadHiddenEvidenceSearch)return;const q=document.getElementById('hesQuery'),kind=document.getElementById('hesKind'),results=document.getElementById('hesResults'),status=document.getElementById('hesStatus'),file=document.getElementById('hesFile');const DB='wereadPrivateEvidenceV1',STORE='evidence',META='meta';let cache=[];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const webSearch=title=>'https://weread.qq.com/web/search/books?keyword='+encodeURIComponent(String(title||'').trim());function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(STORE))db.createObjectStore(STORE,{keyPath:'id'});if(!db.objectStoreNames.contains(META))db.createObjectStore(META,{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}async function loadDb(){const db=await openDb();const tx=db.transaction([STORE,META],'readonly'),a=tx.objectStore(STORE).getAll(),m=tx.objectStore(META).get('stats');return await new Promise((resolve,reject)=>{tx.oncomplete=()=>resolve({items:a.result||[],stats:m.result?.value||null});tx.onerror=()=>reject(tx.error)})}async function saveDb(items,stats){const db=await openDb();const tx=db.transaction([STORE,META],'readwrite'),s=tx.objectStore(STORE);s.clear();items.forEach(x=>s.put(x));tx.objectStore(META).put({key:'stats',value:stats});return await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}async function clearDb(){const db=await openDb();const tx=db.transaction([STORE,META],'readwrite');tx.objectStore(STORE).clear();tx.objectStore(META).clear();return await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}function flatten(payload){const books=Array.isArray(payload)?payload:[];const out=[];let marks=0,reviews=0;books.forEach((b,bi)=>{const bid=String(b.bookId||b.book?.bookId||''),title=String(b.title||b.book?.title||''),author=String(b.author||b.book?.author||'');(b.marks||[]).forEach((x,i)=>{const text=String(x?.text||'').trim();if(!text)return;marks++;out.push({id:`m:${bid}:${x.bookmarkId||x.range||i}:${bi}`,kind:'mark',bookId:bid,title,author,chapter:String(x.chapter||''),text,hay:(title+' '+author+' '+String(x.chapter||'')+' '+text).toLowerCase()})});(b.reviews||[]).forEach((x,i)=>{const text=String(x?.content||x?.text||'').trim();if(!text)return;reviews++;out.push({id:`r:${bid}:${x.reviewId||x.range||i}:${bi}`,kind:'review',bookId:bid,title,author,chapter:String(x.chapter||''),text,hay:(title+' '+author+' '+String(x.chapter||'')+' '+text).toLowerCase()})})});return {items:out,stats:{marks,reviews,total:out.length,importedAt:new Date().toISOString()}}}function updateStatus(stats){status.textContent=stats?`本浏览器已索引 ${stats.marks.toLocaleString()} 条划线 + ${stats.reviews.toLocaleString()} 条想法 · 共 ${stats.total.toLocaleString()} 条`:'尚未导入本地笔记。'}function render(){const needle=(q.value||'').trim().toLowerCase(),k=kind.value;if(!cache.length){results.innerHTML='<div class="hes-empty">首次使用请导入本地 <code>weread_notes_export.json</code>。</div>';return}if(!needle){results.innerHTML='<div class="hes-empty">输入关键词开始搜索。支持正文、书名、作者和章节。</div>';return}const found=[];for(const x of cache){if(k!=='all'&&x.kind!==k)continue;if(x.hay.includes(needle)){found.push(x);if(found.length>=80)break}}if(!found.length){results.innerHTML='<div class="hes-empty">没有匹配结果。</div>';return}results.innerHTML=found.map(x=>`<article class="hes-result"><div><span class="kind">${x.kind==='mark'?'划线':'想法'}</span><b>《${esc(x.title||'未命名')}》</b></div><div class="meta">${esc(x.author||'')}${x.chapter?' · '+esc(x.chapter):''}</div><div class="text">${esc(x.text)}</div>${x.title?`<a href="${esc(webSearch(x.title))}" target="_blank" rel="noopener">在微信读书网页版查找 ↗</a>`:''}</article>`).join('')}function shortExcerpt(text,maxChars=90){const raw=String(text||'').replace(/\s+/g,' ').trim();if(raw.length<=maxChars)return {excerpt:raw,truncated:false};let out=raw.slice(0,maxChars),cut=Math.max(...['。','！','？','!','?','；',';'].map(p=>out.lastIndexOf(p)));if(cut>=Math.max(18,Math.floor(maxChars*.55)))out=out.slice(0,cut+1);return {excerpt:out.trimEnd()+'…',truncated:true}}async function sampleMarks(limit=48,maxChars=90){const data=cache.length?{items:cache}:await loadDb(),marks=(data.items||[]).filter(x=>x.kind==='mark'&&String(x.text||'').trim());if(!marks.length)return [];const pool=[...marks];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}const out=[],books=new Set();for(const x of pool){const key=x.bookId||x.title||x.id;if(books.has(key))continue;books.add(key);const ex=shortExcerpt(x.text,maxChars);out.push({bookId:x.bookId||'',title:x.title||'',author:x.author||'',chapter:x.chapter||'',excerpt:ex.excerpt,truncated:ex.truncated,sourceKind:'mark',webLink:webSearch(x.title||'')});if(out.length>=limit)break}return out}async function hydrate(){try{const data=await loadDb();cache=data.items||[];updateStatus(data.stats);render()}catch(e){status.textContent='本地索引读取失败：'+e.message}}function open(){overlay.hidden=false;overlay.setAttribute('aria-hidden','false');hydrate().then(()=>q.focus())}function close(){overlay.hidden=true;overlay.setAttribute('aria-hidden','true')}window.WeReadHiddenEvidenceSearch={open,close,sampleMarks,hydrate};document.getElementById('hesClose').onclick=close;overlay.addEventListener('click',e=>{if(e.target===overlay)close()});q.addEventListener('input',render);kind.addEventListener('change',render);document.getElementById('hesImport').onclick=()=>file.click();file.addEventListener('change',async()=>{const f=file.files?.[0];if(!f)return;status.textContent='正在本地建立索引…';try{const payload=JSON.parse(await f.text()),flat=flatten(payload);await saveDb(flat.items,flat.stats);cache=flat.items;updateStatus(flat.stats);render()}catch(e){status.textContent='导入失败：'+e.message}finally{file.value=''}});document.getElementById('hesForget').onclick=async()=>{await clearDb();cache=[];updateStatus(null);render()};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.shiftKey&&e.key.toLowerCase()==='f'){e.preventDefault();overlay.hidden?open():close();return}if(!overlay.hidden&&e.key==='Escape'){e.preventDefault();close()}});window.addEventListener('open-weread-private-search',open);if(new URLSearchParams(location.search).get('privateSearch')==='1')open()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot()})();
'''
